-- Migration 098: P17-B port identity crosswalk and versioned geospatial layer.
BEGIN;

-- Reuses P16 ports, pks_sites and pks_port_routes; no duplicate port or PKS master.
CREATE TABLE public.port_external_id_crosswalk (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), port_id uuid NOT NULL REFERENCES public.ports(id) ON DELETE RESTRICT, source_id uuid NOT NULL REFERENCES public.maritime_data_sources(id) ON DELETE RESTRICT, external_record_id text NOT NULL, external_code text, match_method text NOT NULL DEFAULT 'manual', match_confidence numeric(5,4), review_status text NOT NULL DEFAULT 'pending', source_reference text NOT NULL, evidence_sha256 text, source_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid REFERENCES public.users(id), reviewed_by uuid REFERENCES public.users(id), reviewed_at timestamptz, review_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT port_crosswalk_source_record_uq UNIQUE(source_id, external_record_id), CONSTRAINT port_crosswalk_match_method_ck CHECK(match_method IN ('manual','official_code','unlocode','name_location','coordinate','fuzzy_candidate')), CONSTRAINT port_crosswalk_confidence_ck CHECK(match_confidence IS NULL OR (match_confidence >= 0 AND match_confidence <= 1)), CONSTRAINT port_crosswalk_review_status_ck CHECK(review_status IN ('pending','matched','rejected','superseded')), CONSTRAINT port_crosswalk_evidence_sha_ck CHECK(evidence_sha256 IS NULL OR evidence_sha256 ~ '^[0-9a-f]{64}$'), CONSTRAINT port_crosswalk_review_stamp_ck CHECK((review_status='matched' AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND length(btrim(COALESCE(review_note,'')))>=5) OR review_status<>'matched')
);
CREATE UNIQUE INDEX port_crosswalk_source_code_uq ON public.port_external_id_crosswalk(source_id,external_code) WHERE external_code IS NOT NULL;
CREATE INDEX port_crosswalk_port_idx ON public.port_external_id_crosswalk(port_id,review_status);
ALTER TABLE public.port_external_id_crosswalk ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.port_external_id_crosswalk FORCE ROW LEVEL SECURITY;
CREATE POLICY p17b_crosswalk_admin_select ON public.port_external_id_crosswalk FOR SELECT TO app_runtime_secure USING(public.pke_is_platform_admin());
CREATE POLICY p17b_crosswalk_admin_insert ON public.port_external_id_crosswalk FOR INSERT TO app_runtime_secure WITH CHECK(public.pke_is_platform_admin());
CREATE POLICY p17b_crosswalk_admin_update ON public.port_external_id_crosswalk FOR UPDATE TO app_runtime_secure USING(public.pke_is_platform_admin()) WITH CHECK(public.pke_is_platform_admin());
CREATE POLICY p17b_crosswalk_admin_delete ON public.port_external_id_crosswalk FOR DELETE TO app_runtime_secure USING(public.pke_is_platform_admin());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.port_external_id_crosswalk TO app_runtime_secure;
CREATE TABLE public.port_geospatial_features (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), port_id uuid REFERENCES public.ports(id) ON DELETE RESTRICT, pks_site_id uuid REFERENCES public.pks_sites(id) ON DELETE RESTRICT, source_id uuid NOT NULL REFERENCES public.maritime_data_sources(id) ON DELETE RESTRICT, source_feature_id text NOT NULL, feature_type text NOT NULL, geometry_geojson jsonb NOT NULL, geometry_sha256 text NOT NULL, dataset_version text NOT NULL, license_code text NOT NULL, attribution_text text NOT NULL, source_reference text NOT NULL, review_status text NOT NULL DEFAULT 'pending', version_no integer NOT NULL DEFAULT 1, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, created_by uuid REFERENCES public.users(id), reviewed_by uuid REFERENCES public.users(id), reviewed_at timestamptz, review_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT port_geo_subject_ck CHECK((port_id IS NOT NULL)::int + (pks_site_id IS NOT NULL)::int = 1), CONSTRAINT port_geo_type_ck CHECK(feature_type IN ('port_point','terminal_point','port_boundary','terminal_boundary','pks_point','pks_boundary','road_access','road_route')), CONSTRAINT port_geo_json_ck CHECK(jsonb_typeof(geometry_geojson)='object' AND geometry_geojson ? 'type' AND geometry_geojson ? 'coordinates'), CONSTRAINT port_geo_hash_ck CHECK(geometry_sha256 ~ '^[0-9a-f]{64}$'), CONSTRAINT port_geo_version_ck CHECK(version_no > 0), CONSTRAINT port_geo_validity_ck CHECK(valid_to IS NULL OR valid_to > valid_from), CONSTRAINT port_geo_review_ck CHECK(review_status IN ('pending','verified','rejected','superseded')), CONSTRAINT port_geo_license_ck CHECK(length(btrim(license_code))>0 AND length(btrim(attribution_text))>0), CONSTRAINT port_geo_review_stamp_ck CHECK((review_status='verified' AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL AND length(btrim(COALESCE(review_note,'')))>=5) OR review_status<>'verified'), CONSTRAINT port_geo_source_version_uq UNIQUE(source_id,source_feature_id,dataset_version,version_no)
);
CREATE INDEX port_geo_port_type_idx ON public.port_geospatial_features(port_id,feature_type,review_status,version_no DESC);
CREATE INDEX port_geo_pks_type_idx ON public.port_geospatial_features(pks_site_id,feature_type,review_status,version_no DESC);
ALTER TABLE public.port_geospatial_features ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.port_geospatial_features FORCE ROW LEVEL SECURITY;
CREATE POLICY p17b_geo_admin_all ON public.port_geospatial_features FOR ALL TO app_runtime_secure USING(public.pke_is_platform_admin()) WITH CHECK(public.pke_is_platform_admin());
CREATE POLICY p17b_geo_project_read ON public.port_geospatial_features FOR SELECT TO app_runtime_secure USING ((port_id IS NOT NULL AND public.pke_p16_project_port_permission(NULLIF(current_setting('app.current_project_id',true),'')::uuid,port_id,'port.view')) OR (pks_site_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.pks_port_routes r JOIN public.project_pks_site_participation part ON part.pks_site_id=r.pks_site_id WHERE r.pks_site_id=port_geospatial_features.pks_site_id AND r.is_active AND part.project_id=NULLIF(current_setting('app.current_project_id',true),'')::uuid AND part.status='active' AND public.pke_has_project_permission(part.project_id,'route.estimate'))));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.port_geospatial_features TO app_runtime_secure;
ALTER TABLE public.pks_port_routes ADD COLUMN IF NOT EXISTS route_geometry_feature_id uuid REFERENCES public.port_geospatial_features(id) ON DELETE SET NULL;
ALTER TABLE public.pks_port_routes ADD COLUMN IF NOT EXISTS distance_method text;
ALTER TABLE public.pks_port_routes ADD CONSTRAINT pks_port_routes_distance_method_ck CHECK(distance_method IS NULL OR distance_method IN ('straight_line','road_network','operator_quote','gps_track','manual_estimate'));
CREATE INDEX pks_port_routes_verified_priority_idx ON public.pks_port_routes(pks_site_id,verification_status,is_active,distance_km) WHERE route_mode='road';
COMMIT;
